-- =====================================================================
--  MTEC Informática - banco de dados EMBUTIDO (H2)
--  Convertido do dump MySQL BancoMtec25_06.sql (mesmos dados e estrutura).
--  Executado automaticamente pelo sistema na 1ª abertura (uma instrução por linha).
-- =====================================================================
CREATE TABLE cliente (idCliente INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR_IGNORECASE(100) NOT NULL, cpf_cnpj VARCHAR_IGNORECASE(20) NOT NULL, telefone VARCHAR_IGNORECASE(15) NOT NULL, endereco VARCHAR_IGNORECASE(255) DEFAULT NULL, ativo INT DEFAULT 1, CONSTRAINT uq_cpf_cnpj UNIQUE (cpf_cnpj));
CREATE TABLE tecnico (idTECNICO INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR_IGNORECASE(100) NOT NULL, cpf VARCHAR_IGNORECASE(14) DEFAULT NULL, telefone VARCHAR_IGNORECASE(15) DEFAULT NULL, email VARCHAR_IGNORECASE(100) DEFAULT NULL, especialidade VARCHAR_IGNORECASE(100) DEFAULT NULL, status VARCHAR_IGNORECASE(20) DEFAULT 'Ativo' NOT NULL, observacoes VARCHAR_IGNORECASE(255) DEFAULT NULL, login VARCHAR_IGNORECASE(45) DEFAULT NULL, senha VARCHAR_IGNORECASE(100) DEFAULT NULL, CONSTRAINT uq_tecnico_cpf UNIQUE (cpf), CONSTRAINT uq_tecnico_login UNIQUE (login));
CREATE TABLE produto (idPRODUTO INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tipo VARCHAR_IGNORECASE(45) DEFAULT NULL, marca VARCHAR_IGNORECASE(45) DEFAULT NULL, modelo VARCHAR_IGNORECASE(45) DEFAULT NULL, especificacoes VARCHAR_IGNORECASE(255) DEFAULT NULL, CLIENTE_idCliente INT NOT NULL, CONSTRAINT fk_produto_cliente FOREIGN KEY (CLIENTE_idCliente) REFERENCES cliente (idCliente) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE servico (idSERVICO INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data_abertura DATE NOT NULL, prazo_entrega DATE DEFAULT NULL, data_conclusao DATE DEFAULT NULL, status_os VARCHAR_IGNORECASE(45) DEFAULT 'Aguardando Aprovacao' NOT NULL, CLIENTE_idCliente INT NOT NULL, TECNICO_idTECNICO INT DEFAULT NULL, PRODUTO_idPRODUTO INT DEFAULT NULL, CONSTRAINT fk_servico_cliente FOREIGN KEY (CLIENTE_idCliente) REFERENCES cliente (idCliente) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT fk_servico_produto FOREIGN KEY (PRODUTO_idPRODUTO) REFERENCES produto (idPRODUTO) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT fk_servico_tecnico FOREIGN KEY (TECNICO_idTECNICO) REFERENCES tecnico (idTECNICO) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE relatorio_orcamento (idRELATORIO_ORCAMENTO INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, defeito_relatado VARCHAR_IGNORECASE(200) DEFAULT NULL, diagnostico_tecnico VARCHAR_IGNORECASE(45) DEFAULT NULL, pecas_orcadas VARCHAR_IGNORECASE(45) DEFAULT NULL, mao_obra_orcada DECIMAL(10,2) DEFAULT NULL, valor_total_orcamento DECIMAL(10,2) DEFAULT NULL, status_orcamento VARCHAR_IGNORECASE(45) DEFAULT NULL, abertura DATE DEFAULT NULL, validade DATE DEFAULT NULL, CLIENTE_idCliente INT DEFAULT NULL, SERVICO_idSERVICO INT DEFAULT NULL, PRODUTO_idPRODUTO INT DEFAULT NULL, TECNICO_idTECNICO INT DEFAULT NULL, CONSTRAINT fk_orcamento_cliente FOREIGN KEY (CLIENTE_idCliente) REFERENCES cliente (idCliente), CONSTRAINT fk_relatorio_produto FOREIGN KEY (PRODUTO_idPRODUTO) REFERENCES produto (idPRODUTO) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT fk_relatorio_servico FOREIGN KEY (SERVICO_idSERVICO) REFERENCES servico (idSERVICO) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT fk_relatorio_tecnico FOREIGN KEY (TECNICO_idTECNICO) REFERENCES tecnico (idTECNICO) ON DELETE SET NULL ON UPDATE CASCADE);

